536	/**
537	 * Charge the saved card off-session (no customer present).
538	 *
539	 * Two independent idempotency guards, because this moves real money on a timer
540	 * that retries:
541	 *  1. `marker` — pre-flight lookup of a live PaymentIntent for this exact purpose.
542	 *     Survives forever, catches the crash-after-capture window.
543	 *  2. `idempotencyKey` — Stripe replays the identical request instead of charging
544	 *     twice when two sweeps overlap. Only good for 24h, hence guard 1.
545	 */
546	export async function chargeSavedCardOffSession(opts: {
547	  user: CardUser;
548	  amountCents: number;
549	  description: string;
550	  marker: string;
551	  idempotencyKey: string;
552	  metadata?: Record<string, string>;
553	}): Promise<OffSessionResult> {
554	  const { user, amountCents, description, marker, idempotencyKey } = opts;
555	  if (!stripeConfigured()) return { ok: false, kind: "unavailable", message: "Stripe is not configured" };
556	  if (!user.stripeCustomerId || !user.stripePaymentMethodId) {
557	    return { ok: false, kind: "unavailable", message: "No saved card" };
558	  }
559	  // `walletSplit` already keeps the card leg at or above Stripe's floor; this is
560	  // the belt-and-braces check so a future caller can't send a rejectable amount.
561	  if (amountCents < STRIPE_MIN_CENTS) {
562	    return { ok: false, kind: "unavailable", message: `Below Stripe minimum (${STRIPE_MIN_CENTS}c)` };
563	  }
564	
565	  // Guard 1: did we already charge for this purpose?
566	  try {
567	    const existing = await findChargeByMarker(user.stripeCustomerId, marker);
568	    if (existing?.status === "succeeded") {
569	      return {
570	        ok: true,
571	        paymentIntentId: existing.id,
572	        amountCents: existing.amount_received || existing.amount,
573	        replayed: true,
574	      };
575	    }
576	    if (existing?.status === "requires_action") {
577	      // A 3-D Secure wall does not move: retrying the SAME card off-session hits it
578	      // again, so reuse the existing intent (and its link) rather than piling up a
579	      // new challenge every retry. A DIFFERENT card is a different story — if the
580	      // customer has since saved one, cancel the stale challenge and really try it,
581	      // otherwise saving a new card would silently change nothing.
582	      const pendingPm =
583	        typeof existing.payment_method === "string"
584	          ? existing.payment_method
585	          : (existing.payment_method?.id ?? null);
586	      if (pendingPm === user.stripePaymentMethodId) {
587	        return {
588	          ok: false,
589	          kind: "requires_action",
590	          paymentIntentId: existing.id,
591	          message: "Awaiting bank confirmation",
592	        };
593	      }
594	      await cancelIfUnconfirmed(existing.id);
595	    }
596	    if (existing?.status === "processing") {
597	      return { ok: false, kind: "transient", message: "A charge for this period is still settling" };
598	    }
599	  } catch (e) {
600	    // A failed lookup must not become a blind second charge.
601	    console.error("[cards] pre-flight charge lookup failed", e);
602	    return { ok: false, kind: "transient", message: "Could not verify existing charges" };
603	  }
604	
605	  try {
606	    const pi = await stripe().paymentIntents.create(
607	      {
608	        amount: amountCents,
609	        currency: "usd",
610	        customer: user.stripeCustomerId,
611	        payment_method: user.stripePaymentMethodId,
612	        confirm: true,
613	        off_session: true,
614	        // No browser exists here, so a redirect-based next_action could never be
615	        // satisfied — and asking for one is what makes Stripe demand a return_url.
616	        automatic_payment_methods: { enabled: true, allow_redirects: "never" },
617	        description,
618	        metadata: { ...(opts.metadata ?? {}), nxeonUserId: user.id, nxeonChargeKey: marker },
619	      },
620	      { idempotencyKey },
621	    );
622	    if (pi.status === "succeeded") {
623	      return { ok: true, paymentIntentId: pi.id, amountCents: pi.amount_received || pi.amount, replayed: false };
624	    }
625	    if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
626	      return { ok: false, kind: "requires_action", paymentIntentId: pi.id, message: "Bank confirmation required" };
627	    }
628	    if (pi.status === "processing") {
629	      return { ok: false, kind: "transient", message: "Payment is still processing" };
630	    }
631	    return { ok: false, kind: "declined", message: `Payment could not be completed (${pi.status})` };
632	  } catch (e) {
633	    return classifyChargeError(e);
634	  }
635	}
636	
637	/**
638	 * Split a charge failure into the three cases that deserve different treatment:
639	 * the bank wants the customer to confirm, the bank said no, or nothing about the
640	 * customer went wrong at all.
641	 *
642	 * The default is `transient` on purpose. A misclassified transient error costs us
643	 * a delayed renewal; a misclassified decline costs a paid-up customer their
644	 * server. Unknown always resolves to the direction that cannot suspend anyone.
645	 */
646	function classifyChargeError(e: unknown): OffSessionResult {
647	  const err = asStripeError(e);
648	  const message = String(err?.message ?? (e as Error)?.message ?? e).slice(0, 300);
649	  if (!err) return { ok: false, kind: "transient", message };
650	
651	  // 3-D Secure surfaces as a card error with this code, with the PI attached.
652	  if (err.code === "authentication_required" || err.payment_intent?.status === "requires_action") {
653	    return {
654	      ok: false,
655	      kind: "requires_action",
656	      paymentIntentId: err.payment_intent?.id ?? null,
657	      message,
658	    };
659	  }
660	  if (err.rawType === "card_error") {
661	    return { ok: false, kind: "declined", message, code: err.decline_code ?? err.code };
662	  }
663	  // The saved method vanished at Stripe (detached elsewhere, customer deleted).
664	  // Not a decline — there is nothing to retry until a new card is saved.
665	  if (err.rawType === "invalid_request_error" && err.code === "resource_missing") {
666	    return { ok: false, kind: "unavailable", message };
667	  }
668	  return { ok: false, kind: "transient", message };
669	}
