671	/** Drop a stale payment method so the UI stops claiming a card is on file. */
672	export async function forgetMissingPaymentMethod(userId: string): Promise<void> {
673	  await clearCardColumns(userId);
674	  await db.auditLog.create({
675	    data: {
676	      userId,
677	      action: "card.missing_at_stripe",
