683	/**
684	 * Credit the wallet for money a card just paid, exactly once.
685	 *
686	 * Idempotency is the UNIQUE index on `WalletTransaction.stripePaymentIntentId`,
687	 * NOT a read-then-write check: a retried sweep and a replayed Stripe request can
688	 * both arrive with the same intent id, and only the database can safely pick the
689	 * winner. P2002 means someone already credited it — that is a success, not an error.
690	 *
691	 * No invoice for a renewal leg: the renewal transaction issues one PAID invoice
692	 * for the whole renewal, and a second document for the card portion would
693	 * double-count the same revenue. Callers that ARE the whole payment (a wallet
694	 * auto-top-up) pass `invoiceDescription` and get one in the same guarded write.
695	 */
696	export async function creditOffSessionCharge(opts: {
697	  userId: string;
698	  amountCents: number;
699	  description: string;
700	  paymentIntentId: string;
701	  invoiceDescription?: string;
702	}): Promise<boolean> {
703	  if (opts.amountCents <= 0) return false;
704	  try {
705	    await db.$transaction([
706	      db.walletTransaction.create({
707	        data: {
708	          userId: opts.userId,
709	          amountCents: opts.amountCents,
710	          description: opts.description,
711	          stripePaymentIntentId: opts.paymentIntentId,
712	        },
713	      }),
714	      db.user.update({
715	        where: { id: opts.userId },
716	        data: { balanceCents: { increment: opts.amountCents } },
717	      }),
718	      ...(opts.invoiceDescription
719	        ? [
720	            db.invoice.create({
721	              data: invoiceCreateData({
722	                userId: opts.userId,
723	                description: opts.invoiceDescription,
724	                status: "PAID",
725	                lineItems: [
726	                  {
727	                    description: opts.invoiceDescription,
728	                    qty: 1,
729	                    unitCents: opts.amountCents,
730	                    amountCents: opts.amountCents,
731	                  },
732	                ],
733	              }),
734	            }),
735	          ]
736	        : []),
737	    ]);
738	    return true;
739	  } catch (e) {
740	    if ((e as { code?: string })?.code === "P2002") return false; // already credited
741	    throw e;
742	  }
743	}
