745	/**
746	 * Hosted Checkout link for an outstanding renewal balance.
747	 *
748	 * Carries ONLY `nxeonUserId` in metadata, which makes the shared, already-proven
749	 * fulfilment path treat it as a wallet top-up: the money lands as wallet credit
750	 * and the next sweep renews from the wallet. That is why this is also the answer
751	 * to 3-D Secure — Checkout collects the bank challenge on Stripe's own page, so we
752	 * never need Stripe.js in the browser or a second confirmation code path.
753	 *
754	 * The quoted amount is the remainder the wallet cannot cover AT THIS MOMENT. If
755	 * the customer spends their credit before paying, the next sweep simply recomputes
756	 * the split and asks the card for the new remainder — it self-heals rather than
757	 * over- or under-charging.
758	 */
759	export async function createOutstandingCheckout(opts: {
760	  user: { id: string; email: string; stripeCustomerId: string | null };
761	  amountCents: number;
762	  hostname: string;
763	  serverId: string;
764	}): Promise<string | null> {
765	  if (!stripeConfigured()) return null;
766	  // Guard the INPUT, not the floored amount. `if (amount <= 0)` sat AFTER the
767	  // `Math.max(STRIPE_MIN_CENTS, …)` below and was therefore dead code: an
768	  // `amountCents` of 0 — a caller whose wallet already covers the renewal, or one
769	  // whose split came back with no card leg — was floored up to 50c and became a
770	  // real hosted-checkout page asking a customer who owes nothing for fifty cents.
771	  // Nothing due means no link, not a minimum charge.
772	  const due = Math.round(opts.amountCents);
773	  if (!Number.isFinite(due) || due <= 0) return null;
774	  // Stripe rejects a charge under its floor, and the surplus is honest here in a
775	  // way it would not be elsewhere: this session credits the WALLET, so a 30c
776	  // balance settled with the 50c minimum leaves the customer 20c of their own
777	  // credit, not 20c of our revenue. The page states the amount it charges.
778	  const amount = Math.max(STRIPE_MIN_CENTS, due);
779	  const base = appBase();
780	  try {
781	    const session = await stripe().checkout.sessions.create({
782	      mode: "payment",
783	      ...(opts.user.stripeCustomerId
784	        ? { customer: opts.user.stripeCustomerId }
785	        : { customer_email: opts.user.email }),
786	      line_items: [
787	        {
788	          price_data: {
789	            currency: "usd",
790	            product_data: {
791	              name: `Nxeon renewal — ${opts.hostname}`,
792	              description:
793	                "Settles the outstanding renewal balance. Added to your Nxeon wallet and applied to this renewal automatically.",
794	            },
795	            unit_amount: amount,
796	          },
797	          quantity: 1,
798	        },
799	      ],
800	      metadata: { nxeonUserId: opts.user.id },
801	      success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
802	      cancel_url: `${base}/dashboard/servers/${opts.serverId}`,
803	    });
804	    return session.url;
805	  } catch (e) {
806	    console.error("[cards] could not create outstanding-balance checkout", e);
807	    return null;
808	  }
809	}
