822	 * it must never be stored there — keeping the two functions apart makes that
823	 * impossible to get wrong.
824	 */
825	export async function createOutstandingEmbedded(opts: {
826	  user: { id: string; email: string; stripeCustomerId: string | null };
827	  amountCents: number;
828	  hostname: string;
829	  serverId: string;
830	}): Promise<EmbeddedCheckout | null> {
831	  if (!stripeConfigured()) return null;
832	  const due = Math.round(opts.amountCents);
833	  if (!Number.isFinite(due) || due <= 0) return null;
834	  const amount = Math.max(STRIPE_MIN_CENTS, due);
835	  const base = appBase();
836	  try {
837	    const session = await stripe().checkout.sessions.create({
838	      mode: "payment",
839	      ...(opts.user.stripeCustomerId
840	        ? { customer: opts.user.stripeCustomerId }
841	        : { customer_email: opts.user.email }),
842	      line_items: [
843	        {
844	          price_data: {
845	            currency: "usd",
846	            product_data: {
847	              name: `Nxeon renewal — ${opts.hostname}`,
848	              description:
849	                "Settles the outstanding renewal balance. Added to your Nxeon wallet and applied to this renewal automatically.",
850	            },
851	            unit_amount: amount,
852	          },
853	          quantity: 1,
854	        },
855	      ],
856	      metadata: { nxeonUserId: opts.user.id },
