870	/**
871	 * Cancel a PaymentIntent, but only while it is still unconfirmed — captured money
872	 * is never touched. Best-effort throughout: an uncancelled intent is inert unless
873	 * something confirms it, and nothing in this codebase ever does.
874	 */
875	async function cancelIfUnconfirmed(paymentIntentId: string): Promise<void> {
876	  try {
877	    const pi = await stripe().paymentIntents.retrieve(paymentIntentId);
878	    if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
879	      await stripe().paymentIntents.cancel(paymentIntentId);
880	    }
881	  } catch {
882	    /* best-effort */
883	  }
884	}
