886	/**
887	 * Clean up an abandoned 3-D Secure challenge once its period has been paid another
888	 * way (usually the hosted link).
889	 *
890	 * A leftover `requires_action` intent is a loaded gun: anything that later confirms
891	 * it takes a second payment for a period that is already settled.
892	 */
893	export async function cancelPendingChargeForMarker(
894	  customerId: string | null,
895	  marker: string,
896	): Promise<void> {
897	  if (!customerId || !stripeConfigured()) return;
898	  try {
899	    const list = await stripe().paymentIntents.list({ customer: customerId, limit: 25 });
900	    for (const pi of list.data) {
901	      if (pi.metadata?.nxeonChargeKey !== marker) continue;
902	      if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
903	        await cancelIfUnconfirmed(pi.id);
904	      }
905	    }
906	  } catch {
907	    /* best-effort */
908	  }
909	}
