2	import { currentUser } from "@/lib/auth";
3	import { stripe, stripeConfigured, stripePublishableKey, EMBEDDED_UI_MODE, EMBEDDED_REQUEST_OPTS } from "@/lib/stripe";
4	import { ensureStripeCustomer } from "@/lib/stripe-cards";
5	import { getSettingInt } from "@/lib/settings";
6	
7	/** Set by `components/customer/CouponField`; read by `topUp`'s demo gateway only. */
8	const COUPON_COOKIE = "nxeon_coupon";
9	
10	export async function POST(req: NextRequest) {
11	  const user = await currentUser();
12	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
13	  if (!stripeConfigured()) {
14	    return NextResponse.json({ error: "Stripe is not configured yet" }, { status: 400 });
15	  }
16	  const { amount } = await req.json().catch(() => ({}));
17	  const dollars = Number(amount);
18	  if (!Number.isFinite(dollars) || dollars > 5000) {
19	    return NextResponse.json({ error: "Amount must be $5–$5000" }, { status: 400 });
20	  }
21	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
22	  const minTopup = await getSettingInt("min_topup_cents", 500);
23	  if (Math.round(dollars * 100) < minTopup) {
24	    return NextResponse.json(
25	      { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}` },
26	      { status: 400 },
27	    );
28	  }
29	
30	  // A promo code must never be silently dropped at the moment money moves.
31	  //
32	  // `CouponField` stores an accepted code in this cookie for an hour, and the ONLY
33	  // reader is the demo gateway in `topUp`. This route charges the card and
34	  // `creditCheckoutSession` credits `session.amount_total` verbatim, so a bonus
35	  // simply cannot be added here — and Stripe's own `discounts` /
36	  // `allow_promotion_codes` are the wrong instrument for a wallet top-up: they
37	  // reduce `amount_total`, which reduces the credit by the same cents, leaving the
38	  // customer exactly where they started. So a cookie surviving into this path
39	  // (e.g. Stripe was configured after the code was accepted) would mean paying
40	  // full price with a code the UI said was applied — the audit's finding #8.
41	  //
42	  // Refuse, say why, and clear the cookie in the same response so the immediate
43	  // retry succeeds. Nothing has been charged at this point: no session exists yet.
44	  const staleCoupon = req.cookies.get(COUPON_COOKIE)?.value?.trim();
45	  if (staleCoupon) {
46	    const shown = staleCoupon.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32).toUpperCase();
47	    const res = NextResponse.json(
48	      {
49	        error: `Promo code ${shown || "on this account"} can’t be applied to a card payment. We’ve removed it — press Add funds again to continue without it.`,
50	      },
51	      { status: 400 },
52	    );
53	    res.cookies.set({ name: COUPON_COOKIE, value: "", path: "/", maxAge: 0 });
54	    return res;
55	  }
56	
57	  const base = process.env.APP_URL ?? "http://localhost:3000";
58	  // Attach the top-up to a Stripe CUSTOMER and save the card so a customer who only
59	  // ever tops up their wallet still gets a chargeable card on file for off-session
60	  // renewals. `customer` replaces `customer_email` (Stripe rejects a session with
61	  // both), and setup_future_usage records the payment method against the customer.
62	  const customerId = await ensureStripeCustomer(user);
63	  const session = await stripe().checkout.sessions.create({
64	    mode: "payment",
65	    customer: customerId,
66	    payment_intent_data: { setup_future_usage: "off_session" },
67	    line_items: [
68	      {
69	        price_data: {
70	          currency: "usd",
71	          product_data: { name: "Nxeon wallet credit" },
72	          unit_amount: Math.round(dollars * 100),
73	        },
74	        quantity: 1,
75	      },
76	    ],
77	    metadata: { nxeonUserId: user.id },
78	    // Embedded: the card form mounts in a modal on OUR billing page. On success
79	    // Stripe navigates the top window to return_url — the same confirm route that
80	    // credits the wallet — so the fulfilment round-trip is byte-for-byte unchanged.
81	    // embedded_page + pinned API version — see EMBEDDED_UI_MODE doc in lib/stripe.ts.
82	    ui_mode: EMBEDDED_UI_MODE,
83	    return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
84	  }, EMBEDDED_REQUEST_OPTS);
85	  return NextResponse.json(
86	    session.client_secret
87	      ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() }
88	      : { error: "Stripe didn't return a session. Please try again." },
89	    session.client_secret ? undefined : { status: 502 },
90	  );
91	}
