import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { packMetadata, STRIPE_METADATA_VALUE_MAX } from "../lib/stripe.ts";

/**
 * Stripe metadata is where this platform keeps the only record of WHAT a payment
 * was for. Everything here defends one property: a session is never created
 * carrying a payload the confirm route cannot read back.
 */

function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

/* ------------------------------------------------------------------ *
 * A truncated intent used to become a silent wallet top-up
 *
 * Every payload was written as `JSON.stringify(x).slice(0, 490)`. A slice through
 * JSON is not JSON, the consumer's JSON.parse throws inside a try that returns
 * null, and fulfilCheckoutSession then cannot see an order/resize/disk-expansion
 * in the session — so it takes its plain top-up branch. Card charged, money in
 * the wallet, NO server, no error, no failure row. Invisible from every surface.
 * ------------------------------------------------------------------ */

test("an oversized payload is refused, never truncated", () => {
  const huge = { hostname: "x".repeat(STRIPE_METADATA_VALUE_MAX) };
  assert.throws(
    () => packMetadata("Order intent", huge),
    (e: Error) => {
      assert.match(e.message, /over Stripe's 500-character metadata limit/);
      // The message has to say what the alternative would have cost, because the
      // alternative is what shipped for months.
      assert.match(e.message, /take the money and provision nothing/);
      return true;
    },
    "an payload that cannot round-trip must throw, not silently lose its tail"
  );
});

test("a payload that fits round-trips byte-for-byte", () => {
  const intent = { planId: "plan_starter", hostname: "my-vps", termMonths: 12, addons: { malware: true } };
  const packed = packMetadata("Order intent", intent);
  assert.ok(packed.length <= STRIPE_METADATA_VALUE_MAX);
  assert.deepEqual(JSON.parse(packed), intent, "what the confirm route parses is what was stamped");
});

test("the boundary is exact — 500 passes, 501 throws", () => {
  // `{"a":"…"}` — 8 characters of envelope plus the padding.
  const fits = { a: "y".repeat(STRIPE_METADATA_VALUE_MAX - 8) };
  const packedFits = packMetadata("boundary", fits);
  assert.equal(packedFits.length, STRIPE_METADATA_VALUE_MAX, "constructed exactly at the cap");
  assert.doesNotThrow(() => packMetadata("boundary", fits));
  assert.throws(() => packMetadata("boundary", { a: "y".repeat(STRIPE_METADATA_VALUE_MAX - 7) }));
});

