/* ------------------------------------------------------------------ *
 * A card that clears must always be a card Nxeon can charge again
 *
 * REAL INCIDENT (2026-08-20). A brand-new customer's VPS order (a real, PAID
 * $8.88 charge — Stripe live PaymentIntent pi_3U6cCsHxcLe3GonT0wFpSrcU) went
 * through `createOrderCheckout` at a moment when that function did not yet set
 * `customer` / `payment_intent_data.setup_future_usage`. The card cleared, the
 * server was provisioned, and the account was left with NO Stripe customer and
 * NO saved payment method — unrenewable by the billing sweep. The very next
 * commit (cf9f9cb) closed that gap on the order/game/host/email/topup paths;
 * this test is the regression guard so it can never reopen on ANY of them, and
 * it extends the same guard to `createResizeCheckout` / `createDiskExpandCheckout`
 * — an upgrade or disk expansion can just as easily be a customer's first-ever
 * card charge (e.g. their original order was fully covered by the wallet or a
 * 100%-off promo), and it must not be the one purchase this codebase forgets to
 * save a card for.
 * ------------------------------------------------------------------ */

/** Every function that opens a Checkout session to collect real money from a
 *  customer for a NEW purchase/upgrade (as opposed to `createOutstandingCheckout`
 *  / `createOutstandingEmbedded`, which settle an existing renewal balance for an
 *  account that — by the time it is dunning — already went through one of these). */
const MONEY_CHECKOUT_FNS = [
  "createOrderCheckout",
  "createGameOrderCheckout",
  "createHostingOrderCheckout",
  "createEmailOrderCheckout",
  "createResizeCheckout",
  "createDiskExpandCheckout",
];

function functionBody(src: string, name: string): string {
  const start = src.indexOf(`function ${name}(`);
  assert.ok(start >= 0, `could not find function ${name} in lib/stripe.ts`);
  // Balance braces from the function's opening `{` to find its real end — these
  // bodies nest object literals and callbacks, so a lazy regex would stop short.
  const openBrace = src.indexOf("{", start);
  let depth = 0;
  for (let i = openBrace; i < src.length; i++) {
    if (src[i] === "{") depth++;
    else if (src[i] === "}") {
      depth--;
      if (depth === 0) return src.slice(start, i + 1);
    }
  }
  throw new Error(`unbalanced braces reading ${name}`);
}

test("every checkout session that can fund a recurring purchase saves the card", () => {
  const src = code("../lib/stripe.ts");
  for (const name of MONEY_CHECKOUT_FNS) {
    const body = functionBody(src, name);
    assert.match(
      body,
      /customer:\s*customerId/,
      `${name} must attach the session to a Stripe CUSTOMER (not customer_email) so the card can be saved`
    );
    assert.match(
      body,
      /payment_intent_data:\s*\{\s*setup_future_usage:\s*"off_session"\s*\}/,
      `${name} must request setup_future_usage: "off_session" — without it the card clears once and is never seen again`
    );
    assert.doesNotMatch(
      body,
      /customer_email:/,
      `${name} must not fall back to customer_email — Stripe rejects a session carrying both customer and customer_email`
    );
  }
});

test("createResizeCheckout / createDiskExpandCheckout resolve a Stripe customer before opening the session", () => {
  const src = code("../lib/stripe.ts");
  for (const name of ["createResizeCheckout", "createDiskExpandCheckout"]) {
    const body = functionBody(src, name);
    assert.match(
      body,
      /ensureStripeCustomer\(user\)/,
      `${name} must get-or-create the Stripe customer, exactly like createOrderCheckout, instead of leaving the session to invent one from customer_email`
    );
  }
});

test("fulfilment records the card for every kind that can be a customer's first card charge", () => {
  const src = code("../lib/fulfil-checkout.ts");
  // One `saveCardFromPaymentSession` call inside each of these branches (order,
  // gameOrder, hostOrder, emailOrder, resize, diskExpand, topup) — a kind missing
  // this call is a kind that can strand a paid customer with no chargeable card,
  // exactly like the 2026-08-20 incident above.
  const kinds = ["order", "gameOrder", "hostOrder", "emailOrder", "resize", "diskExpand", "topup"];
  const calls = (src.match(/saveCardFromPaymentSession\(/g) ?? []).length;
  assert.ok(
    calls >= kinds.length,
    `expected at least one saveCardFromPaymentSession call per fulfilled kind (${kinds.join(", ")}), found ${calls}`
  );
});

