function functionBody(src: string, name: string): string {
  const start = src.indexOf(`function ${name}(`);
  assert.ok(start >= 0, `could not find function ${name} in lib/stripe.ts`);
  // Find the END of the parameter list first (balancing PARENS, not braces) — a
  // param can itself carry an object-type annotation like `resize: { … }`, whose
  // own `{`/`}` would otherwise be mistaken for the function body's braces.
  const parenStart = src.indexOf("(", start);
  let pdepth = 0;
  let parenEnd = -1;
  for (let i = parenStart; i < src.length; i++) {
    if (src[i] === "(") pdepth++;
    else if (src[i] === ")") {
      pdepth--;
      if (pdepth === 0) {
        parenEnd = i;
        break;
      }
    }
  }
  assert.ok(parenEnd >= 0, `unbalanced parens reading ${name}'s parameter list`);
  // Now the function body's opening `{` is the first one after the param list
  // (past any return-type annotation).
  const openBrace = src.indexOf("{", parenEnd);
  let depth = 0;
  for (let i = openBrace; i < src.length; i++) {
    if (src[i] === "{") depth++;
    else if (src[i] === "}") {
      depth--;
      if (depth === 0) return src.slice(start, i + 1);
    }
  }
  throw new Error(`unbalanced braces reading ${name}`);
}

